import math
import numpy as np

Main(
    geometry = "2Dcartesian",
    interpolation_order = 2,
    cell_length = [0.09817477042468103, 0.39269908169872414],
    number_of_cells = [3072, 512],
    timestep = 0.09048134136944434,
    simulation_time = 1298.63345200495,
    number_of_patches = [64, 8],
    EM_boundary_conditions = [["silver-muller"], ["periodic"]],
    solve_poisson = False,
    random_seed = 1,
    print_every = 500,
)

MovingWindow(
    time_start = 256.0,
    velocity_x = 1.0,
)

# The laser is applied 2 cells behind xmin, as sin(t) of the run's time: focus, center and
# phase_offset put the case's pulse (a cosine from the envelope's peak, with the Gouy phase) on x = 0.
# a0 and waist are not the case's 2.0 and 28.0: a0 is divided by the boundary condition's
# launch factor, and the beam is the narrower one (waist² − 1, the same a0·waist) that the condition's
# response to oblique components, 1 − k_y²/4, turns into the case's (smilei_laser in scripts/lwfa/lwfa.jl).
LaserGaussian2D(
    box_side = "xmin",
    a0 = 1.9990474352844985,
    omega = 1.0,
    focus = [320.1963495408494, 100.53096491487338],
    waist = 27.982137159266443,
    polarization_phi = 0.0,
    time_envelope = tgaussian(start = 0.0, duration = 216.0843500232432, fwhm = 43.29283978020028, center = 108.0421750116216),
    phase_offset = 4.238524552470963,
)

DiagScalar(every = 50, precision = 10)

def plasma_density(x, y):
    s = np.clip((x - 260.0) / 60.0, 0.0, 1.0)
    return 0.01 * np.sin(0.5 * math.pi * s)**2

for name, charge, mass, frozen in (("electron", -1.0, 1.0, 0.0), ("ion", 1.0, 1836.15267343, 5194.352845337061)):
    Species(
        name = name,
        position_initialization = "regular",
        regular_number = [2, 2],
        momentum_initialization = "cold",
        particles_per_cell = 4,
        mass = mass,
        charge = charge,
        number_density = plasma_density,
        time_frozen = frozen,
        boundary_conditions = [["remove", "remove"], ["periodic", "periodic"]],
    )

# 0: the window's spectrum; 1 and 2: the same cell by cell over the 96 cells at its back and at its
# front, which the reader takes off outside the region all three codes hold (spectrum_region)
DiagParticleBinning(
    deposited_quantity = "weight",
    every = 1104,
    species = ["electron"],
    axes = [["ekin", 0.0, 100.0, 500]],
)
DiagParticleBinning(
    deposited_quantity = "weight",
    every = 1104,
    species = ["electron"],
    axes = [["moving_x", 0.0, 9.42477796076938, 96], ["ekin", 0.0, 100.0, 500]],
)
DiagParticleBinning(
    deposited_quantity = "weight",
    every = 1104,
    species = ["electron"],
    axes = [["moving_x", 292.16811678385073, 301.59289474462014, 96], ["ekin", 0.0, 100.0, 500]],
)

DiagFields(
    every = 1104,
    fields = ["Ex", "Ey", "Rho_electron"],
    datatype = "double",
)
